import { isCi } from "./env.js";
import { toSnakeCase } from "./utils/string.js";
import { formatHumanChunk, resolveOutputWidth } from "./human_table.js";
import YAML from "yaml";
//#region src/writer.ts
const writeYaml = (chunks) => {
	return YAML.stringify(chunks.length === 1 ? chunks[0].data : Object.fromEntries(chunks.map(({ config, data }, idx) => [config.title ? toSnakeCase(config.title) : idx, data])), null, 2);
};
const writeJson = (chunks) => {
	const json = JSON.stringify(chunks.length === 1 ? chunks[0].data : Object.fromEntries(chunks.map(({ config, data }, idx) => [config.title ? toSnakeCase(config.title) : idx, data])), null, 2);
	return json === void 0 ? json : `${json}\n`;
};
const writeTable = (chunks, out, width) => {
	chunks.forEach(({ data, config }, i) => {
		out.write(formatHumanChunk({
			data,
			fields: config.fields,
			title: config.title,
			emptyMessage: config.emptyMessage,
			renderColumns: config.renderColumns,
			width,
			colorTitle: !isCi(),
			leadingBlank: i > 0 && Boolean(config.title)
		}));
	});
};
/**
*
* Parses the output format, takes data and writes the output to stdout.
*
* @example
* const { data } = await props.apiClient.listProjectBranches(props.project.id);
* // to output single data
* writer(props).end(data, { fields: ['id', 'name', 'created_at'] })
* // to output multiple data
* writer(props)
*   .write(data, { fields: ['id', 'name', 'created_at'], title: 'branches' })
*   .write(data, { fields: ['id', 'created_at'], title: 'endpoints' })
*   .end()
*/
const writer = (props) => {
	const out = props.out ?? process.stdout;
	const width = resolveOutputWidth(out, props.columns, {
		stdout: process.stdout,
		envColumns: process.env.COLUMNS
	});
	const chunks = [];
	return {
		write(data, config) {
			chunks.push({
				data,
				config
			});
			return this;
		},
		text(data) {
			return out.write(data);
		},
		end: (...args) => {
			if (args.length === 2) chunks.push({
				data: args[0],
				config: args[1]
			});
			if (props.output == "yaml") return out.write(writeYaml(chunks));
			if (props.output == "json") return out.write(writeJson(chunks));
			writeTable(chunks, out, width);
		}
	};
};
//#endregion
export { writer };
